import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional

from elasticsearch import Elasticsearch


class ElasticsearchLogQueryError(Exception):
    pass


def query_recent_error_logs(
    severity: str = "ERROR",
    lookback_minutes: int = 60,
    index: str = "logs-*",
    timestamp_field: str = "@timestamp",
    severity_field: str = "log.level",
    message_field: str = "message",
    size: int = 100,
    cloud_id: Optional[str] = None,
    api_key: Optional[str] = None,
) -> List[Dict[str, Any]]:
    cloud_id = cloud_id or os.environ.get("ELASTIC_CLOUD_ID")
    api_key = api_key or os.environ.get("ELASTIC_API_KEY")

    if not cloud_id or not api_key:
        raise ElasticsearchLogQueryError(
            "Missing Elastic Cloud credentials. Set ELASTIC_CLOUD_ID and ELASTIC_API_KEY."
        )

    if lookback_minutes <= 0:
        raise ElasticsearchLogQueryError("lookback_minutes must be greater than 0.")

    client = Elasticsearch(
        cloud_id=cloud_id,
        api_key=api_key,
        request_timeout=30,
    )

    end_time = datetime.now(timezone.utc)
    start_time = end_time - timedelta(minutes=lookback_minutes)

    query = {
        "size": size,
        "sort": [{timestamp_field: {"order": "desc"}}],
        "_source": [timestamp_field, severity_field, message_field, "service.name", "host.name"],
        "query": {
            "bool": {
                "filter": [
                    {
                        "range": {
                            timestamp_field: {
                                "gte": start_time.isoformat(),
                                "lte": end_time.isoformat(),
                            }
                        }
                    },
                    {"term": {severity_field: severity}},
                ]
            }
        },
    }

    try:
        response = client.search(index=index, body=query)
    except Exception as exc:
        raise ElasticsearchLogQueryError(f"Elastic search query failed: {exc}") from exc

    hits = response.get("hits", {}).get("hits", [])
    results: List[Dict[str, Any]] = []

    for hit in hits:
        source = hit.get("_source", {})
        results.append(
            {
                "timestamp": source.get(timestamp_field),
                "severity": source.get(severity_field),
                "message": source.get(message_field),
                "service": source.get("service.name"),
                "host": source.get("host.name"),
                "index": hit.get("_index"),
                "id": hit.get("_id"),
            }
        )

    return results
